const TOPICS = ["বাংলাদেশ বিষয়াবলি (Bangladesh Affairs)", "আন্তর্জাতিক বিষয়াবলি (International Affairs)", "সাধারণ বিজ্ঞান (General Science)", "কম্পিউটার ও তথ্যপ্রযুক্তি (Computer & ICT)", "ভূগোল, পরিবেশ ও দুর্যোগ ব্যবস্থাপনা (Geography, Environment & Disaster Management)", "গাণিতিক যুক্তি (Mathematical Reasoning)", "নৈতিকতা, মূল্যবোধ ও সুশাসন (Ethics, Values & Good Governance)", "মানসিক দক্ষতা (Mental Ability)"];
const staticData = $getWorkflowStaticData('global');
if (typeof staticData.topicIndex !== 'number') staticData.topicIndex = 0;
const topic = TOPICS[staticData.topicIndex % TOPICS.length];
staticData.topicIndex = (staticData.topicIndex + 1) % TOPICS.length;
return { json: { topic } };

